cat >> config.conf <<'EOF'
# SS QLM Auto-Generated Block
section_start {
    property=value
}
EOF

inject_between() {
    local file=$1 start=$2 end=$3
    {
        sed -n "1,/$start/p" "$file"
        cat # Takes content from pipe/stdin
        sed -n "/$end/,$ p" "$file"
    } > "$file.tmp" && mv "$file.tmp" "$file"
}
